package com.sphere.core.clhep.geometry;

import com.sphere.core.clhep.CMath;
import com.sphere.core.clhep.vector.Hep3Vector;
import com.sphere.core.hepmc3.cxx.CIStream;
import com.sphere.core.hepmc3.cxx.COStream;
import com.sphere.core.hepmc3.cxx.StdStreams;

/**
 * CLHEP's HepGeom::BasicVector3D&lt;double&gt; (Geometry/BasicVector3D.h, BasicVector3D.cc): three
 * coordinates and what Point3D, Vector3D and Normal3D share — lengths, angles, rotations, the arithmetic
 * of the free operators (+, -, * by a number, * as the dot product, /).
 * Generated by gen_geometry.py.
 */
public class BasicVector3D {

    public static final int X = 0;
    public static final int Y = 1;
    public static final int Z = 2;
    public static final int NUM_COORDINATES = 3;
    public static final int SIZE = NUM_COORDINATES;

    protected final double[] v_ = new double[3];

    /** (0,0,0): protected in C++, where only Point3D, Vector3D and Normal3D make it. */
    protected BasicVector3D() {
    }

    public BasicVector3D(double x1, double y1, double z1) {
        v_[0] = x1;
        v_[1] = y1;
        v_[2] = z1;
    }

    public BasicVector3D(BasicVector3D v) {
        v_[0] = v.v_[0];
        v_[1] = v.v_[1];
        v_[2] = v.v_[2];
    }

    /** From a BasicVector3D&lt;float&gt;, widened. */
    public BasicVector3D(BasicVector3DF v) {
        v_[0] = v.x();
        v_[1] = v.y();
        v_[2] = v.z();
    }

    /** operator T*: the coordinates themselves. */
    public double[] data() {
        return v_;
    }

    /** operator Hep3Vector. */
    public Hep3Vector toHep3Vector() {
        return new Hep3Vector(x(), y(), z());
    }

    /** operator=. */
    public BasicVector3D assign(BasicVector3D v) {
        v_[0] = v.v_[0];
        v_[1] = v.v_[1];
        v_[2] = v.v_[2];
        return this;
    }

    public BasicVector3D plusAssign(BasicVector3D v) {
        v_[0] += v.v_[0];
        v_[1] += v.v_[1];
        v_[2] += v.v_[2];
        return this;
    }

    public BasicVector3D minusAssign(BasicVector3D v) {
        v_[0] -= v.v_[0];
        v_[1] -= v.v_[1];
        v_[2] -= v.v_[2];
        return this;
    }

    /** operator*=(double): each coordinate times a, in double, stored as double. */
    public BasicVector3D timesAssign(double a) {
        v_[0] *= a;
        v_[1] *= a;
        v_[2] *= a;
        return this;
    }

    public BasicVector3D divAssign(double a) {
        v_[0] /= a;
        v_[1] /= a;
        v_[2] /= a;
        return this;
    }

    /** operator() and operator[]. */
    public double get(int i) {
        return v_[i];
    }

    /** The coordinate i set (T&amp; operator[]). */
    public void set(int i, double a) {
        v_[i] = a;
    }

    public double x() {
        return v_[0];
    }

    public double y() {
        return v_[1];
    }

    public double z() {
        return v_[2];
    }

    public void setX(double a) {
        v_[0] = a;
    }

    public void setY(double a) {
        v_[1] = a;
    }

    public void setZ(double a) {
        v_[2] = a;
    }

    public void set(double x1, double y1, double z1) {
        v_[0] = x1;
        v_[1] = y1;
        v_[2] = z1;
    }

    public double perp2() {
        return x() * x() + y() * y();
    }

    public double perp() {
        return Math.sqrt(perp2());
    }

    public double rho() {
        return perp();
    }

    public void setPerp(double rh) {
        double factor = perp();
        if (factor > 0) {
            factor = rh / factor;
            v_[0] *= factor;
            v_[1] *= factor;
        }
    }

    public double mag2() {
        return x() * x() + y() * y() + z() * z();
    }

    public double mag() {
        return Math.sqrt(mag2());
    }

    public double r() {
        return mag();
    }

    public double phi() {
        return x() == 0 && y() == 0 ? 0 : CMath.atan2(y(), x());
    }

    public double theta() {
        return x() == 0 && y() == 0 && z() == 0 ? 0 : CMath.atan2(perp(), z());
    }

    public double cosTheta() {
        final double ma = mag();
        return ma == 0 ? 1 : z() / ma;
    }

    public double getR() {
        return r();
    }

    public double getPhi() {
        return phi();
    }

    public double getTheta() {
        return theta();
    }

    public void setMag(double ma) {
        double factor = mag();
        if (factor > 0) {
            factor = ma / factor;
            v_[0] *= factor;
            v_[1] *= factor;
            v_[2] *= factor;
        }
    }

    public void setR(double ma) {
        setMag(ma);
    }

    public void setPhi(double ph) {
        final double xy = perp();
        setX(xy * CMath.cos(ph));
        setY(xy * CMath.sin(ph));
    }

    public void setTheta(double th) {
        final double ma = mag();
        final double ph = phi();
        set(ma * CMath.sin(th) * CMath.cos(ph), ma * CMath.sin(th) * CMath.sin(ph), ma * CMath.cos(th));
    }

    /** -log(tan(theta/2)); Double.MAX_VALUE along the axis, 0 for the null vector. */
    public double pseudoRapidity() {
        final double ma = mag();
        final double dz = z();
        if (ma == 0) return 0;
        if (ma == dz) return Double.MAX_VALUE;
        if (ma == -dz) return -Double.MAX_VALUE;
        return (0.5 * CMath.log((ma + dz) / (ma - dz)));
    }

    public double eta() {
        return pseudoRapidity();
    }

    public double getEta() {
        return pseudoRapidity();
    }

    public void setEta(double a) {
        final double ma = mag();
        if (ma == 0) return;
        final double tanHalfTheta = CMath.exp(-a);
        final double tanHalfTheta2 = tanHalfTheta * tanHalfTheta;
        final double cosTheta1 = (1 - tanHalfTheta2) / (1 + tanHalfTheta2);
        final double rh = ma * Math.sqrt(1 - cosTheta1 * cosTheta1);
        final double ph = phi();
        set((rh * CMath.cos(ph)), (rh * CMath.sin(ph)), (ma * cosTheta1));
    }

    public double dot(BasicVector3D v) {
        return x() * v.x() + y() * v.y() + z() * v.z();
    }

    public BasicVector3D cross(BasicVector3D v) {
        return new BasicVector3D(y() * v.z() - v.y() * z(),
            z() * v.x() - v.z() * x(),
            x() * v.y() - v.x() * y());
    }

    /** The square of the component perpendicular to v. */
    public double perp2(BasicVector3D v) {
        final double tot = v.mag2();
        final double s = dot(v);
        return tot > 0 ? mag2() - s * s / tot : mag2();
    }

    public double perp(BasicVector3D v) {
        return Math.sqrt(perp2(v));
    }

    public double angle(BasicVector3D v) {
        double cosa = 0;
        final double ptot = mag() * v.mag();
        if (ptot > 0) {
            cosa = dot(v) / ptot;
            if (cosa > 1) cosa = 1;
            if (cosa < -1) cosa = -1;
        }
        return (CMath.acos(cosa));
    }

    public BasicVector3D unit() {
        final double len = mag();
        return (len > 0) ? new BasicVector3D(x() / len, y() / len, z() / len) : new BasicVector3D();
    }

    public BasicVector3D orthogonal() {
        final double dx = x() < 0 ? -x() : x();
        final double dy = y() < 0 ? -y() : y();
        final double dz = z() < 0 ? -z() : z();
        if (dx < dy) {
            return dx < dz ? new BasicVector3D(0, z(), -y()) : new BasicVector3D(y(), -x(), 0);
        } else {
            return dy < dz ? new BasicVector3D(-z(), 0, x()) : new BasicVector3D(y(), -x(), 0);
        }
    }

    public BasicVector3D rotateX(double a) {
        final double sina = CMath.sin(a);
        final double cosa = CMath.cos(a);
        final double dy = y();
        final double dz = z();
        setY((dy * cosa - dz * sina));
        setZ((dz * cosa + dy * sina));
        return this;
    }

    public BasicVector3D rotateY(double a) {
        final double sina = CMath.sin(a);
        final double cosa = CMath.cos(a);
        final double dz = z();
        final double dx = x();
        setZ((dz * cosa - dx * sina));
        setX((dx * cosa + dz * sina));
        return this;
    }

    public BasicVector3D rotateZ(double a) {
        final double sina = CMath.sin(a);
        final double cosa = CMath.cos(a);
        final double dx = x();
        final double dy = y();
        setX((dx * cosa - dy * sina));
        setY((dy * cosa + dx * sina));
        return this;
    }

    /** A rotation by a around the axis v. */
    public BasicVector3D rotate(double a, BasicVector3D v) {
        if (a == 0) return this;
        double cx = v.x();
        double cy = v.y();
        double cz = v.z();
        final double ll = Math.sqrt(cx * cx + cy * cy + cz * cz);
        if (ll == 0) {
            StdStreams.cerr().print("BasicVector<double>::rotate() : zero axis\n");
            return this;
        }
        final double cosa = CMath.cos(a);
        final double sina = CMath.sin(a);
        cx /= ll;
        cy /= ll;
        cz /= ll;
        final double xx = cosa + (1 - cosa) * cx * cx;
        final double xy = (1 - cosa) * cx * cy - sina * cz;
        final double xz = (1 - cosa) * cx * cz + sina * cy;
        final double yx = (1 - cosa) * cy * cx + sina * cz;
        final double yy = cosa + (1 - cosa) * cy * cy;
        final double yz = (1 - cosa) * cy * cz - sina * cx;
        final double zx = (1 - cosa) * cz * cx - sina * cy;
        final double zy = (1 - cosa) * cz * cy + sina * cx;
        final double zz = cosa + (1 - cosa) * cz * cz;
        cx = x();
        cy = y();
        cz = z();
        set((xx * cx + xy * cy + xz * cz), (yx * cx + yy * cy + yz * cz),
            (zx * cx + zy * cy + zz * cz));
        return this;
    }

    /* ---- the free operators ---- */

    /** +v: a copy. */
    public BasicVector3D plus() {
        return new BasicVector3D(this);
    }

    public BasicVector3D plus(BasicVector3D b) {
        return new BasicVector3D(x() + b.x(), y() + b.y(), z() + b.z());
    }

    public BasicVector3D negate() {
        return new BasicVector3D(-x(), -y(), -z());
    }

    public BasicVector3D minus(BasicVector3D b) {
        return new BasicVector3D(x() - b.x(), y() - b.y(), z() - b.z());
    }

    /** v * a (a double first). */
    public BasicVector3D times(double a) {
        return new BasicVector3D(x() * a, y() * a, z() * a);
    }

    /** a * v. */
    public static BasicVector3D times(double a, BasicVector3D v) {
        return new BasicVector3D(a * v.x(), a * v.y(), a * v.z());
    }

    /** v * w: the dot product. */
    public double times(BasicVector3D b) {
        return dot(b);
    }

    public BasicVector3D div(double a) {
        return new BasicVector3D(x() / a, y() / a, z() / a);
    }

    /** operator==: the same coordinates. */
    public boolean isEqual(BasicVector3D b) {
        return x() == b.x() && y() == b.y() && z() == b.z();
    }

    public boolean notEqual(BasicVector3D b) {
        return x() != b.x() || y() != b.y() || z() != b.z();
    }

    @Override
    public boolean equals(Object o) {
        return o instanceof BasicVector3D b && isEqual(b);
    }

    @Override
    public int hashCode() {
        return java.util.Arrays.hashCode(v_);
    }

    /** operator&lt;&lt;: (x,y,z). */
    public COStream print(COStream os) {
        return os.put("(").put(x()).put(",").put(y()).put(",").put(z()).put(")");
    }

    /** operator&gt;&gt;: (x,y,z); what is wrong said on cerr. */
    public static CIStream read(CIStream is, BasicVector3D a) {
        int c = is.nextChar();
        if (is.fail() || c != '(') {
            StdStreams.cerr().print("Could not find required opening parenthesis in input of a BasicVector3D<double>\n");
            return is;
        }
        final double x = is.nextDouble();
        c = is.nextChar();
        if (is.fail() || c != ',') {
            StdStreams.cerr().print("Could not find x value and required trailing comma in input of a BasicVector3D<double>\n");
            return is;
        }
        final double y = is.nextDouble();
        c = is.nextChar();
        if (is.fail() || c != ',') {
            StdStreams.cerr().print("Could not find y value and required trailing comma in input of a BasicVector3D<double>\n");
            return is;
        }
        final double z = is.nextDouble();
        c = is.nextChar();
        if (is.fail() || c != ')') {
            StdStreams.cerr().print("Could not find z value and required close parenthesis in input of a BasicVector3D<double>\n");
            return is;
        }
        a.setX(x);
        a.setY(y);
        a.setZ(z);
        return is;
    }

    @Override
    public String toString() {
        return print(new COStream()).str();
    }
}
